script:
frappe.ui.form.on("Asset", {

    refresh: function(frm) {

        // Only Active employees
        ["custodian", "custom_custodian2"].forEach(function(field) {

            frm.set_query(field, function() {
                return {
                    filters: {
                        status: "Active"
                    }
                };
            });

        });
    },

    // Custodian selected
    custodian: function(frm) {

        // Clear everything if custodian removed
        if (!frm.doc.custodian) {
            frm.set_value("custom_custodian_name", "");
            frm.set_value("custom_custodian2", "");
            frm.set_value("custom_custodian2_name", "");

            return;
        }

        // Prevent duplicate
        if (
            frm.doc.custodian === frm.doc.custom_custodian2

        ) {

            frm.set_value("custodian", "");
            frm.set_value("custom_custodian_name", "");

            frappe.msgprint({
                title: __("Duplicate Employee"),
                message: __("Custodian, Reports To and Account Manager must all be different."),
                indicator: "red"
            });

            return;
        }

        // Fetch hierarchy from Employee
        frappe.db.get_value("Employee", frm.doc.custodian, [
            "reports_to",
        ]).then(r => {

            if (r.message) {

                frm.set_value("custom_custodian2", r.message.reports_to || "");

            }

        });

    },

    custom_custodian2: function(frm) {

        if (
            frm.doc.custom_custodian2 &&
            (
                frm.doc.custom_custodian2 === frm.doc.custodian

            )
        ) {

            frm.set_value("custom_custodian2", "");
            frm.set_value("custom_custodian2_name", "");

            frappe.msgprint({
                title: __("Duplicate Employee"),
                message: __("Custodian, Reports To and Account Manager must all be different."),
                indicator: "red"
            });
        }

    },

    validate: function(frm) {

        const employees = [
            frm.doc.custodian,
            frm.doc.custom_custodian2
        ].filter(Boolean);

        if (new Set(employees).size !== employees.length) {

            frappe.throw(__("Custodian, Reports To and Account Manager must all be different employees."));

        }

    }

});

frappe.ui.form.on('Asset', {
    refresh: function(frm) {
        // Only run after the Asset record has been created/saved
        if (!frm.is_new()) {
            
            // 1. Build full URL for this specific Asset
            let asset_url = window.location.origin + '/app/asset/' + frm.doc.name;

            // 2. Load external QRCode library dynamically if not loaded
            if (typeof QRCode === 'undefined') {
                frappe.require('https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js', function() {
                    render_asset_qr(frm, asset_url);
                });
            } else {
                render_asset_qr(frm, asset_url);
            }
        }
    }
});

function render_asset_qr(frm, url) {
    // 3. Target your custom HTML field: 'custom_qr_code'
    let wrapper = frm.get_field('custom_qr_code').$wrapper;
    
    // Render HTML container
    wrapper.html(`
        <div style="margin-top: 10px; text-align: left;">
            <div id="qrcode_container"></div>
            <p style="font-size: 11px; color: #8d99a6; margin-top: 5px;">
                Scan to open asset page
            </p>
        </div>
    `);

    // 4. Generate QR code SVG/Canvas
    new QRCode(document.getElementById("qrcode_container"), {
        text: url,
        width: 128,
        height: 128,
        colorDark : "#000000",
        colorLight : "#ffffff",
        correctLevel : QRCode.CorrectLevel.H
    });
}
